package nimbo

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

// ExportValues are the settings of the emulators of a stack as the generated files should show them: a real value,
// or a <NAME> placeholder for a secret nobody asked to see. Settings with no value are absent.
type ExportValues map[string]string

// exportValues collects the values for a set of providers. Secrets are only decrypted when reveal is true.
func exportValues(ctx context.Context, defs []ProviderDef, hostEnv map[string]string, store SecretStore, reveal bool) ExportValues {
	out := ExportValues{}
	for _, def := range defs {
		sources := VarSources(ctx, def, hostEnv, store)
		for _, v := range def.Vars {
			src := sources[v.Name]
			if src == SourceUnset {
				continue
			}
			if v.Secret && !reveal {
				out[v.Name] = "<" + v.Name + ">"
				continue
			}
			if src == SourceEnvironment {
				out[v.Name] = hostEnv[v.Name]
			} else if val, ok, err := store.Get(ctx, v.Name); err == nil && ok {
				out[v.Name] = val
			}
		}
	}
	return out
}

// pick returns the value of a setting or the fallback.
func (v ExportValues) pick(name, fallback string) string {
	if val := v[name]; val != "" {
		return val
	}
	return fallback
}

func exportHas(defs []ProviderDef, id string) bool {
	for _, d := range defs {
		if d.ID == id {
			return true
		}
	}
	return false
}

// ---- docker-compose.yml -------------------------------------------------------------------------------------------

// ExportCompose writes a docker-compose.yml with the emulators of a stack, as Nimbo would run them: ports on loopback,
// the same images, the same environment. Secrets are never in it: they are ${NIMBO_*} references that come from the
// .env file next to it (see ExportComposeEnv). With keepData, the emulators that can keep their data get a named volume.
func ExportCompose(stackID string, defs []ProviderDef, values ExportValues, keepData bool) string {
	var b strings.Builder
	b.WriteString("# Generated by Nimbo. Run it with: docker compose up -d   (stop with: docker compose down)\n")
	b.WriteString("# Passwords and other settings come from the .env file next to this one; this file holds none of them.\n")
	fmt.Fprintf(&b, "name: nimbo-%s\n\nservices:\n", stackID)
	var volumes []string
	for _, def := range defs {
		var keep *PersistSpec
		if keepData {
			keep = def.Persist
		}
		fmt.Fprintf(&b, "  %s:\n    image: %s\n    restart: unless-stopped\n", def.ID, def.Image)
		b.WriteString("    ports:\n")
		for _, p := range def.Ports {
			fmt.Fprintf(&b, "      - \"127.0.0.1:%d:%d\"\n", p, p)
		}
		env := composeEnvironment(def, values, keep)
		if len(env) > 0 {
			b.WriteString("    environment:\n")
			for _, kv := range env {
				fmt.Fprintf(&b, "      %s: %s\n", kv.Key, composeScalar(kv.Value))
			}
		}
		command := def.Command
		if keep != nil && keep.Command != nil {
			command = keep.Command
		}
		if len(command) > 0 {
			b.WriteString("    command: " + composeList(command) + "\n")
		}
		composeRunArgs(&b, def.RunArgs)
		if keep != nil {
			if keep.User != "" {
				fmt.Fprintf(&b, "    user: %q\n", keep.User)
			}
			vol := VolumeName(def)
			b.WriteString("    volumes:\n      - " + vol + ":" + keep.MountPath + "\n")
			volumes = append(volumes, vol)
		}
		b.WriteString("\n")
	}
	if len(volumes) > 0 {
		b.WriteString("volumes:\n")
		for _, v := range volumes {
			b.WriteString("  " + v + ":\n")
		}
	}
	return strings.TrimRight(b.String(), "\n") + "\n"
}

// composeEnvironment is the container environment of a provider: fixed values, settings as references, and the
// environment that only matters when data is kept.
func composeEnvironment(def ProviderDef, values ExportValues, keep *PersistSpec) Vars {
	var out Vars
	for _, kv := range def.ContainerEnv {
		out = append(out, kv)
	}
	if keep != nil {
		out = append(out, keep.Env...)
	}
	for _, v := range def.Vars {
		switch {
		case v.Required:
			out = append(out, KV{v.Container, "${" + v.Name + `:?Set ` + v.Name + ` in the .env file}`})
		case values[v.Name] != "":
			// An optional setting you configured in Nimbo is part of the file; one you did not is left out.
			out = append(out, KV{v.Container, "${" + v.Name + ":-}"})
		}
	}
	return out
}

// composeScalar quotes a value for YAML. A "$" that is not a Compose reference must be doubled.
func composeScalar(s string) string {
	if strings.Contains(s, "${") {
		return `"` + strings.ReplaceAll(s, `"`, `\"`) + `"`
	}
	return `"` + strings.ReplaceAll(strings.ReplaceAll(s, "$", "$$"), `"`, `\"`) + `"`
}

func composeList(items []string) string {
	quoted := make([]string, len(items))
	for i, it := range items {
		raw, _ := json.Marshal(strings.ReplaceAll(it, "$", "$$"))
		quoted[i] = string(raw)
	}
	return "[" + strings.Join(quoted, ", ") + "]"
}

// composeRunArgs translates the few `docker run` flags the catalog uses; anything else is reported, not guessed.
func composeRunArgs(b *strings.Builder, args []string) {
	var tmpfs, hosts []string
	privileged := false
	var unknown []string
	for i := 0; i < len(args); i++ {
		switch a := args[i]; {
		case a == "--privileged":
			privileged = true
		case a == "--tmpfs" && i+1 < len(args):
			i++
			tmpfs = append(tmpfs, args[i])
		case strings.HasPrefix(a, "--add-host="):
			hosts = append(hosts, strings.TrimPrefix(a, "--add-host="))
		default:
			unknown = append(unknown, a)
		}
	}
	if privileged {
		b.WriteString("    privileged: true\n")
	}
	if len(tmpfs) > 0 {
		b.WriteString("    tmpfs:\n")
		for _, t := range tmpfs {
			b.WriteString("      - " + t + "\n")
		}
	}
	if len(hosts) > 0 {
		b.WriteString("    extra_hosts:\n")
		for _, h := range hosts {
			b.WriteString("      - \"" + h + "\"\n")
		}
	}
	if len(unknown) > 0 {
		b.WriteString("    # Nimbo also passes these docker run flags, which have no equivalent here: " + strings.Join(unknown, " ") + "\n")
	}
}

// ExportComposeEnv is the .env file that goes with the compose file. Secrets are placeholders unless they were asked
// for: fill them in, or export again including the passwords.
func ExportComposeEnv(defs []ProviderDef, values ExportValues) string {
	var b strings.Builder
	b.WriteString("# Generated by Nimbo. Keep this file private: it holds passwords and must not be committed.\n")
	for _, def := range defs {
		if len(def.Vars) == 0 {
			continue
		}
		b.WriteString("\n# " + def.Name + "\n")
		for _, v := range def.Vars {
			val := values[v.Name]
			switch {
			case val != "" && !strings.HasPrefix(val, "<"):
				b.WriteString(v.Name + "=" + envFileValue(val) + "\n")
			case v.Required:
				b.WriteString("# Required. Set it here, or export again including the passwords.\n" + v.Name + "=\n")
			default:
				b.WriteString("# Optional.\n# " + v.Name + "=\n")
			}
		}
	}
	return b.String()
}

// envFileValue quotes a value for a .env file only when it needs it.
func envFileValue(v string) string {
	if strings.ContainsAny(v, " #\"'$\\") {
		return `'` + strings.ReplaceAll(v, `'`, `'\''`) + `'`
	}
	return v
}

// ---- Spring Boot: application-nimbo.yml ---------------------------------------------------------------------------

type ynode struct {
	key  string
	val  string
	kids []*ynode
}

func (n *ynode) child(key string) *ynode {
	for _, k := range n.kids {
		if k.key == key {
			return k
		}
	}
	k := &ynode{key: key}
	n.kids = append(n.kids, k)
	return k
}

func (n *ynode) set(path string, value string) {
	cur := n
	for _, p := range strings.Split(path, ".") {
		cur = cur.child(p)
	}
	cur.val = value
}

func (n *ynode) render(b *strings.Builder, depth int) {
	for _, k := range n.kids {
		b.WriteString(strings.Repeat("  ", depth) + k.key + ":")
		if len(k.kids) == 0 {
			b.WriteString(" " + yamlScalar(k.val) + "\n")
			continue
		}
		b.WriteString("\n")
		k.render(b, depth+1)
	}
}

func yamlScalar(s string) string {
	if s == "true" || s == "false" {
		return s
	}
	if s != "" && strings.Trim(s, "0123456789.") == "" && strings.Count(s, ".") <= 1 {
		return s
	}
	raw, _ := marshalNoHTMLEscape(s)
	return string(raw)
}

// ExportSpring is an application-nimbo.yml: start your app with SPRING_PROFILES_ACTIVE=nimbo and it talks to the
// emulators of the stack. Only what the stack contains is written.
func ExportSpring(defs []ProviderDef, v ExportValues) string {
	root := &ynode{}
	if exportHas(defs, "floci-aws") {
		root.set("spring.cloud.aws.region.static", "us-east-1")
		root.set("spring.cloud.aws.credentials.access-key", "test")
		root.set("spring.cloud.aws.credentials.secret-key", "test")
		root.set("spring.cloud.aws.endpoint", ExportAWSEndpoint)
		root.set("spring.cloud.aws.s3.path-style-access-enabled", "true")
	}
	if exportHas(defs, "minio") {
		root.set("nimbo.minio.endpoint", "http://localhost:9000")
		root.set("nimbo.minio.access-key", v.pick("NIMBO_MINIO_USER", "<NIMBO_MINIO_USER>"))
		root.set("nimbo.minio.secret-key", v.pick("NIMBO_MINIO_PASSWORD", "<NIMBO_MINIO_PASSWORD>"))
	}
	if exportHas(defs, "postgres") {
		user, db := v.pick("NIMBO_POSTGRES_USER", "postgres"), v.pick("NIMBO_POSTGRES_DB", v.pick("NIMBO_POSTGRES_USER", "postgres"))
		root.set("spring.datasource.url", "jdbc:postgresql://localhost:5432/"+db)
		root.set("spring.datasource.username", user)
		root.set("spring.datasource.password", v.pick("NIMBO_POSTGRES_PASSWORD", "<NIMBO_POSTGRES_PASSWORD>"))
		root.set("spring.datasource.driver-class-name", "org.postgresql.Driver")
	}
	if exportHas(defs, "redis") {
		root.set("spring.data.redis.host", "localhost")
		root.set("spring.data.redis.port", "6379")
		if pw := v["NIMBO_REDIS_PASSWORD"]; pw != "" {
			root.set("spring.data.redis.password", pw)
		}
	}
	if exportHas(defs, "redpanda") {
		root.set("spring.kafka.bootstrap-servers", "localhost:9092")
	}
	if exportHas(defs, "azurite") {
		root.set("spring.cloud.azure.storage.blob.connection-string", azuriteConnectionString(v))
	}
	if exportHas(defs, "floci-gcp") {
		root.set("spring.cloud.gcp.project-id", "floci-local")
		root.set("spring.cloud.gcp.pubsub.emulator-host", "localhost:4588")
	}
	if exportHas(defs, "jaeger") {
		root.set("management.tracing.sampling.probability", "1.0")
		root.set("management.otlp.tracing.endpoint", "http://localhost:4318/v1/traces")
	}
	var b strings.Builder
	b.WriteString("# Generated by Nimbo. Save as src/main/resources/application-nimbo.yml and run with SPRING_PROFILES_ACTIVE=nimbo.\n")
	if len(root.kids) == 0 {
		b.WriteString("# The emulators of this stack have nothing to configure for Spring.\n")
	}
	root.render(&b, 0)
	return b.String()
}

// azuriteConnectionString is the connection string of Azurite: its development account unless you set your own.
func azuriteConnectionString(v ExportValues) string {
	name, key, ok := strings.Cut(strings.SplitN(v["NIMBO_AZURITE_ACCOUNTS"], ";", 2)[0], ":")
	if !ok || name == "" {
		return "UseDevelopmentStorage=true"
	}
	key = strings.SplitN(key, ":", 2)[0]
	return "DefaultEndpointsProtocol=http;AccountName=" + name + ";AccountKey=" + key +
		";BlobEndpoint=http://127.0.0.1:10000/" + name + ";QueueEndpoint=http://127.0.0.1:10001/" + name + ";TableEndpoint=http://127.0.0.1:10002/" + name + ";"
}

// ---- .NET: appsettings.Nimbo.json ---------------------------------------------------------------------------------

// jobject is a JSON object that keeps the order its keys were added in, so the file reads the way it was written.
type jobject struct {
	keys []string
	vals map[string]any
}

func newJobject() *jobject { return &jobject{vals: map[string]any{}} }

func (o *jobject) put(key string, val any) *jobject {
	if _, ok := o.vals[key]; !ok {
		o.keys = append(o.keys, key)
	}
	o.vals[key] = val
	return o
}

func (o *jobject) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, k := range o.keys {
		if i > 0 {
			buf.WriteByte(',')
		}
		kb, _ := json.Marshal(k)
		vb, err := marshalNoHTMLEscape(o.vals[k])
		if err != nil {
			return nil, err
		}
		buf.Write(kb)
		buf.WriteByte(':')
		buf.Write(vb)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

func marshalNoHTMLEscape(v any) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	return bytes.TrimRight(buf.Bytes(), "\n"), nil
}

// ExportDotnet is an appsettings.Nimbo.json: ASP.NET reads it when ASPNETCORE_ENVIRONMENT=Nimbo, and
// builder.Configuration["ConnectionStrings:Postgres"] and friends are then the emulators.
func ExportDotnet(defs []ProviderDef, v ExportValues) string {
	root := newJobject()
	conns := newJobject()
	if exportHas(defs, "postgres") {
		user, db := v.pick("NIMBO_POSTGRES_USER", "postgres"), v.pick("NIMBO_POSTGRES_DB", v.pick("NIMBO_POSTGRES_USER", "postgres"))
		conns.put("Postgres", "Host=localhost;Port=5432;Database="+db+";Username="+user+";Password="+v.pick("NIMBO_POSTGRES_PASSWORD", "<NIMBO_POSTGRES_PASSWORD>"))
	}
	if exportHas(defs, "redis") {
		cs := "localhost:6379"
		if pw := v["NIMBO_REDIS_PASSWORD"]; pw != "" {
			cs += ",password=" + pw
		}
		conns.put("Redis", cs)
	}
	if exportHas(defs, "azurite") {
		conns.put("AzureStorage", azuriteConnectionString(v))
	}
	if len(conns.keys) > 0 {
		root.put("ConnectionStrings", conns)
	}
	if exportHas(defs, "floci-aws") {
		root.put("AWS", newJobject().put("ServiceURL", ExportAWSEndpoint).put("Region", "us-east-1").put("AccessKey", "test").put("SecretKey", "test"))
	}
	if exportHas(defs, "minio") {
		root.put("MinIO", newJobject().put("Endpoint", "localhost:9000").put("AccessKey", v.pick("NIMBO_MINIO_USER", "<NIMBO_MINIO_USER>")).
			put("SecretKey", v.pick("NIMBO_MINIO_PASSWORD", "<NIMBO_MINIO_PASSWORD>")).put("UseSsl", false))
	}
	if exportHas(defs, "redpanda") {
		root.put("Kafka", newJobject().put("BootstrapServers", "localhost:9092"))
	}
	if exportHas(defs, "floci-gcp") {
		root.put("Gcp", newJobject().put("ProjectId", "floci-local").put("PubSubEmulatorHost", "localhost:4588"))
	}
	if exportHas(defs, "jaeger") {
		root.put("OpenTelemetry", newJobject().put("OtlpEndpoint", "http://localhost:4317"))
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	_ = enc.Encode(root)
	return buf.String()
}

// sortedFormatIDs is used by error messages and tests.
func sortedFormatIDs() []string {
	ids := make([]string, 0, len(exportFormats))
	for _, f := range exportFormats {
		ids = append(ids, f.ID)
	}
	sort.Strings(ids)
	return ids
}
